//! How the engine decides a file is Terminal Delight's: its sha256 appears in
//! the receipt its installer wrote, or in the table of every version of that
//! file TD has ever shipped. A matching name is never enough. The table is
//! generated by `scripts/known-hashes.sh` from git history, so a helper
//! installed from an old checkout is still recognised after the source moved.
use sha2::{Digest, Sha256};
use std::collections::BTreeMap;
use std::io::Read;
use std::path::{Path, PathBuf};

const KNOWN: &str = include_str!("known_hashes.txt");

/// `sha256 -> repo paths` for every shipped version of every installed file.
pub(crate) fn known() -> BTreeMap<String, Vec<String>> {
    let mut m: BTreeMap<String, Vec<String>> = BTreeMap::new();
    for line in KNOWN.lines().map(str::trim) {
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        let mut parts = line.split_whitespace();
        if let (Some(h), Some(p)) = (parts.next(), parts.next()) {
            m.entry(h.to_ascii_lowercase())
                .or_default()
                .push(p.to_string());
        }
    }
    m
}

pub(crate) fn sha256_file(p: &Path) -> std::io::Result<String> {
    let mut f = std::fs::File::open(p)?;
    let mut h = Sha256::new();
    let mut buf = vec![0u8; 1 << 16];
    loop {
        let n = f.read(&mut buf)?;
        if n == 0 {
            break;
        }
        h.update(&buf[..n]);
    }
    Ok(format!("{:x}", h.finalize()))
}

pub(crate) fn sha256_bytes(b: &[u8]) -> String {
    format!("{:x}", Sha256::digest(b))
}

/// One line of an install receipt.
#[derive(Debug, Clone, PartialEq)]
pub(crate) enum Line {
    File { sha256: String, path: PathBuf },
    Hook { settings: PathBuf, command: String },
    Block { file: PathBuf, open: String },
}

#[derive(Debug, Clone, PartialEq)]
pub(crate) struct Receipt {
    pub(crate) component: String,
    pub(crate) path: PathBuf,
    pub(crate) lines: Vec<Line>,
}

/// Every receipt under `<state>/receipts/`. A line that does not parse is
/// kept out rather than guessed at; the receipt still loads.
pub(crate) fn receipts(state_root: &Path) -> Vec<Receipt> {
    let dir = state_root.join("receipts");
    let Ok(rd) = std::fs::read_dir(&dir) else {
        return Vec::new();
    };
    let mut out: Vec<Receipt> = rd
        .flatten()
        .filter_map(|e| {
            let path = e.path();
            let name = path
                .file_name()?
                .to_str()?
                .strip_suffix(".receipt")?
                .to_string();
            let text = std::fs::read_to_string(&path).ok()?;
            Some(Receipt {
                component: name,
                lines: parse_receipt(&text),
                path,
            })
        })
        .collect();
    out.sort_by(|a, b| a.component.cmp(&b.component));
    out
}

pub(crate) fn parse_receipt(text: &str) -> Vec<Line> {
    text.lines()
        .filter(|l| !l.trim().is_empty() && !l.starts_with('#'))
        .filter_map(|l| {
            let f: Vec<&str> = l.splitn(3, '\t').collect();
            match f.as_slice() {
                ["file", h, p] if Path::new(p).is_absolute() => Some(Line::File {
                    sha256: h.to_ascii_lowercase(),
                    path: PathBuf::from(p),
                }),
                ["hook", s, c] if Path::new(s).is_absolute() => Some(Line::Hook {
                    settings: PathBuf::from(s),
                    command: c.to_string(),
                }),
                ["block", f, o] if Path::new(f).is_absolute() => Some(Line::Block {
                    file: PathBuf::from(f),
                    open: o.to_string(),
                }),
                _ => None,
            }
        })
        .collect()
}

/// Why a file counts as TD's, or why it does not.
#[derive(Debug, Clone, PartialEq)]
pub(crate) enum Ownership {
    /// Its hash is in the receipt of `component`.
    Receipt(String),
    /// Its hash is a shipped version of `repo_path`.
    Shipped(String),
    /// It exists but matches nothing TD wrote.
    Unrecognised,
    /// Not a regular file (a symlink, a directory) or unreadable.
    NotAFile(String),
}

impl Ownership {
    pub(crate) fn owned(&self) -> bool {
        matches!(self, Ownership::Receipt(_) | Ownership::Shipped(_))
    }
}

pub(crate) fn ownership(
    path: &Path,
    receipts: &[Receipt],
    known: &BTreeMap<String, Vec<String>>,
) -> (Ownership, Option<String>) {
    match std::fs::symlink_metadata(path) {
        Ok(m) if m.file_type().is_file() => {}
        Ok(_) => return (Ownership::NotAFile("not a regular file".into()), None),
        Err(e) => return (Ownership::NotAFile(e.to_string()), None),
    }
    let hash = match sha256_file(path) {
        Ok(h) => h,
        Err(e) => return (Ownership::NotAFile(e.to_string()), None),
    };
    for r in receipts {
        for l in &r.lines {
            if let Line::File { sha256, path: p } = l {
                if *sha256 == hash && p == path {
                    return (Ownership::Receipt(r.component.clone()), Some(hash));
                }
            }
        }
    }
    if let Some(paths) = known.get(&hash) {
        return (Ownership::Shipped(paths[0].clone()), Some(hash));
    }
    (Ownership::Unrecognised, Some(hash))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn receipt_lines_parse_and_reject_relative_paths() {
        let lines = parse_receipt(
            "# agent-hooks\nfile\tABCD\t/h/.local/bin/td-agent-hooks\nhook\t/h/.claude/settings.json\t/h/.local/bin/td-agent-hooks\nblock\t/h/.config/hypr/bindings.lua\t-- >>> td-keybindings hotkey >>>\nfile\tx\trel/path\ngarbage\n",
        );
        assert_eq!(lines.len(), 3);
        assert_eq!(
            lines[0],
            Line::File {
                sha256: "abcd".into(),
                path: "/h/.local/bin/td-agent-hooks".into()
            }
        );
    }

    #[test]
    fn ownership_needs_a_hash_match_not_a_name() {
        let dir = std::env::temp_dir().join(format!("td-known-{}", std::process::id()));
        std::fs::create_dir_all(&dir).unwrap();
        let f = dir.join("td-agent-hooks");
        std::fs::write(&f, b"#!/bin/sh\necho hi\n").unwrap();
        let h = sha256_file(&f).unwrap();
        let mut known = BTreeMap::new();
        assert_eq!(ownership(&f, &[], &known).0, Ownership::Unrecognised);
        known.insert(h.clone(), vec!["scripts/td-agent-hooks".to_string()]);
        assert!(ownership(&f, &[], &known).0.owned());
        let r = Receipt {
            component: "agent-hooks".into(),
            path: dir.join("x.receipt"),
            lines: vec![Line::File {
                sha256: h,
                path: f.clone(),
            }],
        };
        assert_eq!(
            ownership(&f, &[r], &BTreeMap::new()).0,
            Ownership::Receipt("agent-hooks".into())
        );
        std::os::unix::fs::symlink(&f, dir.join("link")).unwrap();
        assert!(!ownership(&dir.join("link"), &[], &known).0.owned());
        std::fs::remove_dir_all(dir).unwrap();
    }
}
